// Shared pieces of the React auth pages generated by `lila auth --react`.
import type { ReactNode } from "react";
import { useT } from "@lila";
import { ThemeToggle, Toaster } from "./ui";

export interface Provider {
  key: string;
  name: string;
  href: string;
}

export interface SessionUser {
  user_id: number;
  email: string;
  name: string;
}

/** `?next=/app/account` from RequireAuth (only same-site paths). */
export function nextUrl(fallback: string): string {
  const next = new URLSearchParams(window.location.search).get("next") || "";
  return next.startsWith("/") && !next.startsWith("//") ? next : fallback;
}

export function AuthCard({ title, subtitle, children }: { title: string; subtitle?: string; children: ReactNode }) {
  return (
    <main className="relative flex min-h-screen flex-col items-center justify-center px-4 py-12">
      <ThemeToggle className="absolute right-4 top-4" />
      <div className="card w-full max-w-md p-8">
        <div className="mb-6 flex flex-col items-center">
          <img src="/img/lila-128.webp" alt="Lila" width={48} height={48} className="mb-2 rounded-2xl bg-white p-1 shadow-sm" />
          <h1 className="bg-gradient-to-r from-lila-800 via-lila-700 to-lila-500 dark:from-[#e5c2ff] dark:via-lila-300 dark:to-indigo-400 bg-clip-text text-2xl font-black text-transparent">{title}</h1>
          {subtitle && <p className="mt-1 text-xs text-muted-foreground">{subtitle}</p>}
        </div>
        {children}
      </div>
      <Toaster />
    </main>
  );
}

export function OAuthButtons({ providers }: { providers: Provider[] }) {
  const t = useT();
  if (!providers.length) return null;
  return (
    <>
      <div className="mb-6 flex flex-col gap-2.5">
        {providers.map((provider) => (
          // Full navigation: the OAuth flow leaves the app.
          <a key={provider.key} href={provider.href} className="btn-light w-full">
            {t("continue_with", "Continue with")} {provider.name}
          </a>
        ))}
      </div>
      <div className="relative my-6 flex items-center justify-center">
        <div className="w-full border-t border-border" />
        <span className="absolute bg-surface px-3 text-xs font-bold uppercase tracking-wider text-muted-foreground dark:bg-surface-dark">
          {t("or_with_email", "Or with email")}
        </span>
      </div>
    </>
  );
}
